    43	/**
    44	 * @internal
    45	 *
    46	 * @brief Handle a SSH_DISCONNECT packet.
    47	 */
    48	SSH_PACKET_CALLBACK(ssh_packet_disconnect_callback){
    49	  int rc;
    50	  uint32_t code = 0;
    51	  char *error = NULL;
    52	  ssh_string error_s;
    53	  (void)user;
    54	  (void)type;
    55	
    56	  rc = ssh_buffer_get_u32(packet, &code);
    57	  if (rc != 0) {
    58	    code = ntohl(code);
    59	  }
    60	
    61	  error_s = ssh_buffer_get_ssh_string(packet);
    62	  if (error_s != NULL) {
    63	    error = ssh_string_to_char(error_s);
    64	    ssh_string_free(error_s);
    65	  }
    66	  SSH_LOG(SSH_LOG_PACKET, "Received SSH_MSG_DISCONNECT %d:%s",
    67	                          code, error != NULL ? error : "no error");
    68	  ssh_set_error(session, SSH_FATAL,
    69	      "Received SSH_MSG_DISCONNECT: %d:%s",
    70	      code, error != NULL ? error : "no error");
    71	  SAFE_FREE(error);
    72	
    73	  ssh_socket_close(session->socket);
    74	  session->alive = 0;
    75	  session->session_state = SSH_SESSION_STATE_ERROR;
    76	  /* TODO: handle a graceful disconnect */
    77	  return SSH_PACKET_USED;
    78	}
