    95	SSH_PACKET_CALLBACK(ssh_packet_dh_reply){
    96	  int rc;
    97	  (void)type;
    98	  (void)user;
    99	  SSH_LOG(SSH_LOG_PROTOCOL,"Received SSH_KEXDH_REPLY");
   100	  if (session->session_state != SSH_SESSION_STATE_DH ||
   101	                session->dh_handshake_state != DH_STATE_INIT_SENT){
   102	        ssh_set_error(session,SSH_FATAL,"ssh_packet_dh_reply called in wrong state : %d:%d",
   103	                        session->session_state,session->dh_handshake_state);
   104	        goto error;
   105	  }
   106	  switch(session->next_crypto->kex_type){
   107	    case SSH_KEX_DH_GROUP1_SHA1:
   108	    case SSH_KEX_DH_GROUP14_SHA1:
   109	      rc=ssh_client_dh_reply(session, packet);
   110	      break;
   111	#ifdef HAVE_ECDH
   112	    case SSH_KEX_ECDH_SHA2_NISTP256:
   113	    case SSH_KEX_ECDH_SHA2_NISTP384:
   114	    case SSH_KEX_ECDH_SHA2_NISTP521:
   115	      rc = ssh_client_ecdh_reply(session, packet);
   116	      break;
   117	#endif
   118	#ifdef HAVE_CURVE25519
   119	    case SSH_KEX_CURVE25519_SHA256:
   120	    case SSH_KEX_CURVE25519_SHA256_LIBSSH_ORG:
   121	      rc = ssh_client_curve25519_reply(session, packet);
   122	      break;
   123	#endif
   124	    default:
   125	      ssh_set_error(session,SSH_FATAL,"Wrong kex type in ssh_packet_dh_reply");
   126	      goto error;
   127	  }
   128	  if(rc==SSH_OK) {
   129	    session->dh_handshake_state = DH_STATE_NEWKEYS_SENT;
   130	    return SSH_PACKET_USED;
   131	  }
   132	error:
   133	  session->session_state=SSH_SESSION_STATE_ERROR;
   134	  return SSH_PACKET_USED;
   135	}
