   137	SSH_PACKET_CALLBACK(ssh_packet_newkeys){
   138	  ssh_string sig_blob = NULL;
   139	  int rc;
   140	  (void)packet;
   141	  (void)user;
   142	  (void)type;
   143	  SSH_LOG(SSH_LOG_PROTOCOL, "Received SSH_MSG_NEWKEYS");
   144	
   145	  if (session->session_state != SSH_SESSION_STATE_DH ||
   146	      session->dh_handshake_state != DH_STATE_NEWKEYS_SENT) {
   147	      ssh_set_error(session,
   148	                    SSH_FATAL,
   149	                    "ssh_packet_newkeys called in wrong state : %d:%d",
   150	                    session->session_state,session->dh_handshake_state);
   151	      goto error;
   152	  }
   153	
   154	  if(session->server){
   155	    /* server things are done in server.c */
   156	    session->dh_handshake_state=DH_STATE_FINISHED;
   157	  } else {
   158	    ssh_key server_key;
   159	
   160	    /* client */
   161	    rc = ssh_make_sessionid(session);
   162	    if (rc != SSH_OK) {
   163	      goto error;
   164	    }
   165	
   166	    /*
   167	     * Set the cryptographic functions for the next crypto
   168	     * (it is needed for ssh_generate_session_keys for key lengths)
   169	     */
   170	    rc = crypt_set_algorithms_client(session);
   171	    if (rc < 0) {
   172	        goto error;
   173	    }
   174	
   175	    if (ssh_generate_session_keys(session) < 0) {
   176	      goto error;
   177	    }
   178	
   179	    /* Verify the host's signature. FIXME do it sooner */
   180	    sig_blob = session->next_crypto->dh_server_signature;
   181	    session->next_crypto->dh_server_signature = NULL;
   182	
   183	    /* get the server public key */
   184	    server_key = ssh_dh_get_next_server_publickey(session);
   185	    if (server_key == NULL) {
   186	        return SSH_ERROR;
   187	    }
   188	
   189	    /* check if public key from server matches user preferences */
   190	    if (session->opts.wanted_methods[SSH_HOSTKEYS]) {
   191	        if(!ssh_match_group(session->opts.wanted_methods[SSH_HOSTKEYS],
   192	                            server_key->type_c)) {
   193	            ssh_set_error(session,
   194	                          SSH_FATAL,
   195	                          "Public key from server (%s) doesn't match user "
   196	                          "preference (%s)",
   197	                          server_key->type_c,
   198	                          session->opts.wanted_methods[SSH_HOSTKEYS]);
   199	            return -1;
   200	        }
   201	    }
   202	
   203	    rc = ssh_pki_signature_verify_blob(session,
   204	                                       sig_blob,
   205	                                       server_key,
   206	                                       session->next_crypto->secret_hash,
   207	                                       session->next_crypto->digest_len);
   208	    ssh_string_burn(sig_blob);
   209	    ssh_string_free(sig_blob);
   210	    sig_blob = NULL;
   211	    if (rc == SSH_ERROR) {
   212	      goto error;
   213	    }
   214	    SSH_LOG(SSH_LOG_PROTOCOL,"Signature verified and valid");
   215	
   216	    /*
   217	     * Once we got SSH2_MSG_NEWKEYS we can switch next_crypto and
   218	     * current_crypto
   219	     */
   220	    if (session->current_crypto) {
   221	      crypto_free(session->current_crypto);
   222	      session->current_crypto=NULL;
   223	    }
   224	
   225	    /* FIXME later, include a function to change keys */
   226	    session->current_crypto = session->next_crypto;
   227	
   228	    session->next_crypto = crypto_new();
   229	    if (session->next_crypto == NULL) {
   230	      ssh_set_error_oom(session);
   231	      goto error;
   232	    }
   233	    session->next_crypto->session_id = malloc(session->current_crypto->digest_len);
   234	    if (session->next_crypto->session_id == NULL) {
   235	      ssh_set_error_oom(session);
   236	      goto error;
   237	    }
   238	    memcpy(session->next_crypto->session_id, session->current_crypto->session_id,
   239	            session->current_crypto->digest_len);
   240	    if (session->current_crypto->in_cipher->set_decrypt_key(session->current_crypto->in_cipher, session->current_crypto->decryptkey,
   241	        session->current_crypto->decryptIV) < 0) {
   242	      goto error;
   243	    }
   244	    if (session->current_crypto->out_cipher->set_encrypt_key(session->current_crypto->out_cipher, session->current_crypto->encryptkey,
   245	        session->current_crypto->encryptIV) < 0) {
   246	      goto error;
   247	    }
   248	  }
   249	  session->dh_handshake_state = DH_STATE_FINISHED;
   250	  session->ssh_connection_callback(session);
   251	        return SSH_PACKET_USED;
   252	error:
   253	        session->session_state=SSH_SESSION_STATE_ERROR;
   254	        return SSH_PACKET_USED;
   255	}
