   274	/**
   275	 * @internal
   276	 * @brief handles a SSH2_MSG_EXT_INFO packet defined in RFC 8308
   277	 *
   278	 */
   279	SSH_PACKET_CALLBACK(ssh_packet_ext_info)
   280	{
   281	    int rc;
   282	    uint32_t nr_extensions = 0;
   283	    uint32_t i;
   284	    (void)type;
   285	    (void)user;
   286	
   287	    SSH_LOG(SSH_LOG_PACKET, "Received SSH_MSG_EXT_INFO");
   288	
   289	    rc = ssh_buffer_get_u32(packet, &nr_extensions);
   290	    if (rc == 0) {
   291	        SSH_LOG(SSH_LOG_PACKET, "Failed to read number of extensions");
   292	        return SSH_PACKET_USED;
   293	    }
   294	
   295	    nr_extensions = ntohl(nr_extensions);
   296	    if (nr_extensions > 128) {
   297	        SSH_LOG(SSH_LOG_PACKET, "Invalid number of extensions");
   298	        return SSH_PACKET_USED;
   299	    }
   300	
   301	    SSH_LOG(SSH_LOG_PACKET, "Follows %u extensions", nr_extensions);
   302	
   303	    for (i = 0; i < nr_extensions; i++) {
   304	        char *name = NULL;
   305	        char *value = NULL;
   306	        int cmp;
   307	
   308	        rc = ssh_buffer_unpack(packet, "ss", &name, &value);
   309	        if (rc != SSH_OK) {
   310	            SSH_LOG(SSH_LOG_PACKET, "Error reading extension name-value pair");
   311	            return SSH_PACKET_USED;
   312	        }
   313	
   314	        cmp = strcmp(name, "server-sig-algs");
   315	        if (cmp == 0) {
   316	            /* TODO check for NULL bytes */
   317	            SSH_LOG(SSH_LOG_PACKET, "Extension: %s=<%s>", name, value);
   318	            if (ssh_match_group(value, "rsa-sha2-512")) {
   319	                session->extensions |= SSH_EXT_SIG_RSA_SHA512;
   320	            }
   321	            if (ssh_match_group(value, "rsa-sha2-256")) {
   322	                session->extensions |= SSH_EXT_SIG_RSA_SHA256;
   323	            }
   324	        }
   325	        free(name);
   326	        free(value);
   327	    }
   328	
   329	    return SSH_PACKET_USED;
   330	}
